<?php
defined('ABSPATH') || exit;
final class TAAI_Mobile_Account_Deletion { public static function run(WP_REST_Request $r) { global $wpdb;$id=TAAI_Mobile_Security::user_id();$user=get_userdata($id);if(!$user||user_can($user,'manage_options'))return new WP_Error('taai_deletion_forbidden','This account cannot be deleted here.',['status'=>403]);if(!wp_check_password((string)$r['password'],$user->user_pass,$id))return new WP_Error('taai_reauthentication_failed','Password confirmation failed.',['status'=>401]);$wpdb->delete("{$wpdb->prefix}taai_mobile_sessions",['user_id'=>$id]);$wpdb->delete("{$wpdb->prefix}taai_mobile_push_tokens",['user_id'=>$id]);$anonymous='deleted-'.$id.'@invalid.taai.local';wp_update_user(['ID'=>$id,'user_email'=>$anonymous,'display_name'=>'Deleted TAAI User','first_name'=>'','last_name'=>'']);foreach(['billing_phone','billing_address_1','billing_address_2','billing_city','billing_postcode','billing_state','billing_country','shipping_first_name','shipping_last_name','shipping_address_1','shipping_address_2','shipping_city','shipping_postcode','shipping_state','shipping_country'] as $key)delete_user_meta($id,$key);update_user_meta($id,'taai_mobile_deleted',1);return ['success'=>true,'behaviour'=>'Account login disabled and personal profile anonymised. WooCommerce transaction records are retained for legal and accounting obligations.']; } }

